module bst_builder(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] data_in,\n    output reg [7:0] cumulative_sum,\n    output reg done\n);\n    // State declarations\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] TRAVERSE = 3'd1;\n    localparam [2:0] INSERT   = 3'd2;\n    localparam [2:0] DONE_ST  = 3'd3;\n    reg [2:0] state, next_state;\n\n    // Node storage (8 nodes)\n    reg         node_valid [0:7];\n    reg [7:0]   node_value[0:7];\n    reg [2:0]   node_left [0:7];  // 3'b111 = null\n    reg [2:0]   node_right[0:7];\n\n    // Tree management registers\n    reg [2:0] root_idx;         // Current root\n    reg [2:0] next_node_idx;    // Next available node\n    reg [2:0] current_node_idx; // Traversal pointer\n    reg [2:0] parent_node_idx;  // Parent during insertion\n    reg       is_left_child;    // Direction from parent\n    reg [2:0] depth_counter;    // Current depth\n\n    integer i; // Loop variable\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            state <= IDLE;\n            cumulative_sum <= 8'd0;\n            done <= 1'b0;\n            root_idx <= 3'b111;\n            next_node_idx <= 3'd0;\n            current_node_idx <= 3'b111;\n            parent_node_idx <= 3'b111;\n            is_left_child <= 1'b0;\n            depth_counter <= 3'd0;\n            // Initialize all nodes\n            for (i = 0; i < 8; i = i + 1) begin\n                node_valid[i] <= 1'b0;\n                node_value[i] <= 8'd0;\n                node_left[i]  <= 3'b111;\n                node_right[i] <= 3'b111;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        depth_counter <= 3'd0;\n                        current_node_idx <= root_idx;\n                        parent_node_idx <= 3'b111;\n                        state <= TRAVERSE;\n                    end\n                end\n\n                TRAVERSE: begin\n                    if (root_idx == 3'b111) begin // Empty tree\n                        state <= INSERT;\n                    end else if (!node_valid[current_node_idx]) begin\n                        state <= INSERT; // Shouldn't happen\n                    end else if (data_in < node_value[current_node_idx]) begin\n                        // Traverse left\n                        if (node_left[current_node_idx] == 3'b111) begin\n                            parent_node_idx <= current_node_idx;\n                            is_left_child <= 1'b1;\n                            state <= INSERT;\n                        end else begin\n                            parent_node_idx <= current_node_idx;\n                            current_node_idx <= node_left[current_node_idx];\n                            depth_counter <= depth_counter + 3'd1;\n                        end\n                    end else if (data_in > node_value[current_node_idx]) begin\n                        // Traverse right\n                        if (node_right[current_node_idx] == 3'b111) begin\n                            parent_node_idx <= current_node_idx;\n                            is_left_child <= 1'b0;\n                            state <= INSERT;\n                        end else begin\n                            parent_node_idx <= current_node_idx;\n                            current_node_idx <= node_right[current_node_idx];\n                            depth_counter <= depth_counter + 3'd1;\n                        end\n                    end else begin\n                        state <= DONE_ST; // Duplicate (but input guarantees distinct)\n                    end\n                end\n\n                INSERT: begin\n                    // Create new node\n                    node_valid[next_node_idx] <= 1'b1;\n                    node_value[next_node_idx] <= data_in;\n                    node_left[next_node_idx] <= 3'b111;\n                    node_right[next_node_idx] <= 3'b111;\n\n                    // Update parent link\n                    if (parent_node_idx != 3'b111) begin\n                        if (is_left_child) begin\n                            node_left[parent_node_idx] <= next_node_idx;\n                        end else begin\n                            node_right[parent_node_idx] <= next_node_idx;\n                        end\n                    end else begin // Inserting root\n                        root_idx <= next_node_idx;\n                        depth_counter <= 3'd0; // Root depth=0\n                    end\n\n                    // Update cumulative_sum\n                    cumulative_sum <= cumulative_sum + depth_counter;\n                    next_node_idx <= next_node_idx + 3'd1;\n                    state <= DONE_ST;\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule